198	    // ---------------- 权限辅助（先于幂等回放执行） ----------------
199	
200	    private Actor requireActor() {
201	        Actor actor = actorContext.get();
202	        if (actor == null) {
203	            throw ApiException.unauthorized("缺少操作者身份头");
204	        }
205	        return actor;
206	    }
