package com.example.starter.blind.dto;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotNull;

/**
 * 创建实验请求体。
 *
 * @param blockCount 区组数量，2～8，创建时固定；每组固定 4 个席位
 */
public record CreateExperimentRequest(
        @NotNull(message = "blockCount 不能为空")
        @Min(value = 2, message = "区组数量必须在 2~8 之间")
        @Max(value = 8, message = "区组数量必须在 2~8 之间")
        Integer blockCount
) {
}

package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 揭盲申请请求体。
 *
 * @param reason 揭盲原因，必填
 */
public record UnblindApplyRequest(
        @NotBlank(message = "reason 不能为空")
        @Size(max = 500, message = "reason 最长 500 字符")
        String reason
) {
}

package com.example.starter.blind.dto;

/**
 * 揭盲结果视图，包含处理代码；仅申请人本人在申请已批准后可获取。
 *
 * @param requestId     揭盲申请编号
 * @param experimentId  实验编号
 * @param participantId 参与者编号
 * @param treatment     处理代码 A / B
 * @param status        申请状态（返回时必为 APPROVED）
 * @param reviewedAt    批准时间，Unix 毫秒，UTC
 */
public record UnblindResultView(
        String requestId,
        String experimentId,
        String participantId,
        String treatment,
        String status,
        long reviewedAt
) {
}

package com.example.starter.blind.dto;

/**
 * 统一错误响应体。
 *
 * @param error   错误类型标识
 * @param message 安全提示信息（不含盲底）
 */
public record ErrorBody(String error, String message) {
}

