package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 处理代码退役请求体。
 *
 * @param codes  待退役的处理代码集合；至少一个，元素为单个字母（大小写不敏感，
 *               服务端规范化为去重排序后的大写集合再裁决）
 * @param reason 退役理由，必填，写入后不可变
 */
public record RetireCodesRequest(
        @NotEmpty(message = "codes 不能为空")
        List<@NotBlank(message = "处理代码不能为空") String> codes,
        @NotBlank(message = "reason 不能为空")
        @Size(max = 500, message = "reason 最长 500 字符")
        String reason
) {
}

package com.example.starter.blind.dto;

/**
 * 退役代码配额快照视图：记录退役时刻的统计，写入后不可变。
 *
 * @param treatment      被退役的处理代码
 * @param allocatedCount 退役时已分配席位数（既有参与者分配保持有效）
 * @param sealedCount    退役时封存的未分配序号数
 * @param quotaBefore    退役前该代码总配额（每区组2席 × 当时区组数）
 * @param quotaAfter     退役后该代码剩余可分配配额，恒为 0
 */
public record RetiredCodeView(
        String treatment,
        int allocatedCount,
        int sealedCount,
        int quotaBefore,
        int quotaAfter
) {
}

package com.example.starter.blind.dto;

/**
 * 封存序号视图：仅出现在退役明细（COORDINATOR 限定）中；
 * 封存的都是未分配席位，不含任何参与者的盲底信息。
 *
 * @param treatment 封存席位对应的处理代码
 * @param blockNo   封存席位所在区组号
 * @param seatNo    封存席位号
 * @param sealedAt  封存时间，Unix 毫秒，UTC
 */
public record SealedSeatView(
        String treatment,
        int blockNo,
        int seatNo,
        long sealedAt
) {
}

package com.example.starter.blind.dto;

import java.util.List;

/**
 * 退役批次摘要视图：不含封存席位明细，历史列表与明细查询共用。
 *
 * @param retirementId 退役批次编号
 * @param experimentId 所属实验编号
 * @param reason       退役理由（不可变）
 * @param actorId      执行退役的操作者编号
 * @param createdAt    退役时间，Unix 毫秒，UTC
 * @param codes        本批次退役的代码及配额快照，按处理代码升序
 */
public record RetirementView(
        String retirementId,
        String experimentId,
        String reason,
        String actorId,
        long createdAt,
        List<RetiredCodeView> codes
) {
}

